use super::*;
use crate::state::{StateZone,tests::{corpus,receive,source,grant,observe,drain,denied_axes}};
#[test]
fn native_entity_lookup_retains_exact_original_row_through_resumption_and_cancellation(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let rows=(1..=law["rowCount"].as_u64().unwrap()).map(|id|{let mut row=corpus()["model"]["zones"][0].clone();row["id"]=id.into();row["name"]=format!("Original zone {id}").into();row}).collect::<Vec<_>>();let original=source(receive::<PersistentList<StateZone>>(&rows.into()));
 for case in law["cases"].as_array().unwrap(){let key=source(case["id"].as_u64().unwrap()as u32);for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut lookup=RetainedEntityLookup::<StateZone>::new();let mut turns=0;while lookup.result().is_none()&&cut.is_none_or(|cut|turns<cut){let d=lookup.demand(original.borrow(),key.borrow()).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||lookup.advance(original.borrow(),key.borrow(),denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(lookup.demand(original.borrow(),key.borrow()).unwrap(),d);}let(s,h)=observe(||lookup.advance(original.borrow(),key.borrow(),g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));turns+=1;assert!(turns<10000);}let mut retained=None;if cut.is_none(){let expected=case["rank"].as_u64().map(|n|n as usize);assert_eq!(lookup.result(),Some(expected));if let Some(rank)=expected{let row=lookup.row().unwrap().borrow().unwrap();assert_eq!(row.get()as*const StateZone,original.borrow().get().get(rank).unwrap()as*const StateZone);assert_eq!(row.get().id.0,*key.borrow().get());let g=grant(lookup.take_demand().unwrap());let(row,p)=lookup.take(g).unwrap().unwrap();assert!(p.fits(g));retained=Some(row);}}
 lookup.begin_close();for _ in 0..10000{if lookup.terminal_is_empty(){break;}let g=grant(lookup.close_demand(4096).unwrap());let(s,h)=observe(||lookup.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(lookup.terminal_is_empty());assert_eq!(observe(||drop(lookup)).1,(0,0));if let Some(mut row)=retained{assert_eq!(row.borrow().unwrap().get().id.0,*key.borrow().get());for _ in 0..10000{if row.terminal_is_empty(){break;}let g=grant(row.close_demand(4096).unwrap());let(s,h)=observe(||row.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(row.terminal_is_empty());}}
 drain(key);}drain(original);
}
